import { zdrRequest } from "./retention.mjs";
import OpenAI from "openai";
import { ResponsesWS } from "openai/resources/responses/ws";

/**
 * One stateless Responses conversation. The owner serializes sends and closes it
 * after reporting. Host-provided transports remain on their selected HTTP route.
 */
export function createResponsesSession({
  apiKey,
  requestAI,
  record = async () => {},
}) {
  const history = new Map();
  const client = requestAI
    ? null
    : new OpenAI({
        apiKey,
        baseURL: "https://api.openai.com/v1",
        maxRetries: 0,
      });
  let socket,
    cachedId,
    httpOnly = Boolean(requestAI),
    closed = false;
  // Recording observes an event; its edits must not change transport or history.
  const recordEvent = (event) => record(structuredClone(event));
  const http =
    requestAI ??
    ((body, signal) =>
      fetch("https://api.openai.com/v1/responses", {
        method: "POST",
        redirect: "error",
        headers: {
          Authorization: `Bearer ${apiKey}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(body),
        signal,
      }));

  function closeSocket() {
    socket?.close();
    socket = undefined;
    cachedId = undefined;
  }
  function replay(body) {
    const turns = [];
    let id = body.previous_response_id;
    while (id) {
      const prior = history.get(id);
      if (!prior) throw new Error("Runner continuation history unavailable");
      turns.push(prior);
      id = prior.previous;
    }
    const request = { ...body };
    delete request.previous_response_id;
    // The physical wire is caller-owned; callbacks may normalize it. Keep the
    // retained task, output and encrypted reasoning isolated from those edits.
    const input = structuredClone([
      ...turns.reverse().flatMap((turn) => [...turn.input, ...turn.output]),
      ...body.input,
    ]);
    // OpenAI validates replayed computer outputs against the current tools too.
    // A tool-free recap keeps tool selection disabled after restoring the schema.
    const needsComputer =
      input.some((item) => item.type === "computer_call_output") &&
      !request.tools?.some((tool) => tool.type === "computer");
    return {
      ...request,
      input,
      ...(needsComputer
        ? {
            tools: [...(request.tools ?? []), { type: "computer" }],
            ...(!request.tools?.length ? { tool_choice: "none" } : {}),
          }
        : {}),
    };
  }
  function retain(body, response) {
    if (typeof response?.id === "string" && Array.isArray(response.output))
      history.set(response.id, {
        previous: body.previous_response_id,
        input: structuredClone(body.input),
        output: structuredClone(response.output),
      });
  }
  async function connect(signal) {
    if (socket?.socket.readyState === 1) return;
    closeSocket();
    const current = new ResponsesWS(client, { reconnect: null });
    socket = current;
    // The SDK emits a protocol error again after its raw event. The active
    // waiter handles transport errors; keep idle/error-event cleanup observed.
    current.on("error", () => {});
    await new Promise((resolve, reject) => {
      const cleanup = () => {
        current.socket.off("open", opened);
        current.off("error", failed);
        current.off("close", failed);
        signal?.removeEventListener("abort", aborted);
      };
      const opened = () => {
        cleanup();
        resolve();
      };
      const failed = () => {
        cleanup();
        reject(new Error("Runner WebSocket connection unavailable"));
      };
      const aborted = () => {
        cleanup();
        closeSocket();
        reject(signal.reason);
      };
      current.socket.on("open", opened);
      current.on("error", failed);
      current.on("close", failed);
      signal?.addEventListener("abort", aborted, { once: true });
      if (signal?.aborted) aborted();
      else if (current.socket.readyState === 1) opened();
    });
  }
  async function websocket(body, signal) {
    const current = socket;
    return new Promise((resolve, reject) => {
      const cleanup = () => {
        current.off("event", event);
        current.off("error", failed);
        current.off("close", failed);
        signal?.removeEventListener("abort", aborted);
      };
      const event = (value) => {
        if (
          ![
            "response.completed",
            "response.failed",
            "response.incomplete",
            "error",
          ].includes(value.type)
        )
          return;
        cleanup();
        resolve(value);
      };
      const failed = () => {
        cleanup();
        closeSocket();
        reject(
          new Error(
            "Runner WebSocket response interrupted; inference outcome unknown",
          ),
        );
      };
      const aborted = () => {
        cleanup();
        closeSocket();
        reject(signal.reason);
      };
      current.on("event", event);
      current.on("error", failed);
      current.on("close", failed);
      signal?.addEventListener("abort", aborted, { once: true });
      if (signal?.aborted) {
        aborted();
        return;
      }
      const request = { ...body };
      delete request.stream;
      delete request.background;
      try {
        current.send({ type: "response.create", ...request });
      } catch (error) {
        cleanup();
        closeSocket();
        reject(error);
      }
    });
  }
  async function sendHttp(original, signal) {
    const wire = replay(original);
    await recordEvent({ transport: "http", phase: "request", body: wire });
    signal?.throwIfAborted();
    const response = await http(wire, signal);
    // Read a clone so the owner retains the original status/headers/body.
    let body;
    try {
      body = await response.clone().json();
    } catch {
      /* Owner handles malformed bodies. */
    }
    await recordEvent({
      transport: "http",
      phase: "response",
      status: response.status,
      body,
    });
    if (response.ok) retain(original, body);
    return response;
  }
  return {
    async send(request, signal) {
      if (closed) throw new Error("Runner Responses session is closed");
      signal?.throwIfAborted();
      const original = structuredClone({
        ...zdrRequest(request),
        include: [
          ...new Set([
            ...(request.include ?? []),
            "reasoning.encrypted_content",
          ]),
        ],
      });
      if (httpOnly) return sendHttp(original, signal);
      try {
        await connect(signal);
      } catch {
        signal?.throwIfAborted();
        closeSocket();
        httpOnly = true;
        await recordEvent({
          transport: "websocket",
          phase: "unavailable-before-dispatch",
        });
        return sendHttp(original, signal);
      }
      const wire =
        original.previous_response_id &&
        original.previous_response_id === cachedId
          ? original
          : replay(original);
      await recordEvent({
        transport: "websocket",
        phase: "request",
        body: wire,
      });
      signal?.throwIfAborted();
      const event = await websocket(wire, signal);
      await recordEvent({
        transport: "websocket",
        phase: "response",
        body: event,
      });
      if (event.type === "error") {
        cachedId = undefined;
        if (event.error?.code === "previous_response_not_found")
          return sendHttp(original, signal);
        const status =
          event.status ??
          event.error?.status ??
          (event.error?.type === "rate_limit_error"
            ? 429
            : event.error?.type === "server_error"
              ? 500
              : 400);
        return Response.json({ error: event.error }, { status });
      }
      cachedId = event.response.id;
      retain(original, event.response);
      return Response.json(event.response);
    },
    close() {
      closed = true;
      closeSocket();
      history.clear();
    },
  };
}
